pub fn drain(&mut self, count: usize) {
        unsafe {
            use std::ptr;
            ptr::copy(
                self.data.as_ptr().offset(count as isize),
                self.data.as_mut_ptr(),
                self.offset - count,
            );
        }

        self.offset -= count;
    }

